# infra/variables.tf
variable "env" {
  type = string
}

variable "s3_endpoint" {
  description = "S3 endpoint; empty string means real AWS"
  type        = string
  default     = "http://localhost:4566"
}

variable "region" {
  type    = string
  default = "us-east-1"
}

# infra/main.tf
terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80"
    }
  }
}

locals {
  local_mode = var.s3_endpoint != ""
  layers     = ["raw", "bronze", "silver", "gold"]
}

provider "aws" {
  region = var.region

  # These blocks are no-ops against real AWS (credentials come from the environment there).
  access_key                  = local.local_mode ? "test" : null
  secret_key                  = local.local_mode ? "test" : null
  skip_credentials_validation = local.local_mode
  skip_requesting_account_id  = local.local_mode
  skip_metadata_api_check     = local.local_mode
  s3_use_path_style           = local.local_mode

  dynamic "endpoints" {
    for_each = local.local_mode ? [1] : []
    content {
      s3 = var.s3_endpoint
    }
  }

  default_tags {
    tags = {
      project     = "data-platform"
      environment = var.env
      managed_by  = "terraform"
    }
  }
}

# infra/buckets.tf
resource "aws_s3_bucket" "layer" {
  for_each = toset(local.layers)
  bucket   = "lake-${var.env}-${each.key}"
}

resource "aws_s3_bucket_versioning" "layer" {
  for_each = aws_s3_bucket.layer
  bucket   = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "layer" {
  for_each                = aws_s3_bucket.layer
  bucket                  = each.value.id
  block_public_acls       = true
  block_public_policy      = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "raw" {
  bucket = aws_s3_bucket.layer["raw"].id
  rule {
    id     = "expire-raw"
    status = "Enabled"
    filter {}
    expiration {
      days = var.env == "prod" ? 90 : 7
    }
  }
}

# infra/outputs.tf
output "buckets" {
  value = { for k, b in aws_s3_bucket.layer : k => b.bucket }
}

# infra/policy.tf
data "aws_iam_policy_document" "deny_unencrypted" {
  for_each = var.env == "prod" ? aws_s3_bucket.layer : {}
  statement {
    sid       = "DenyUnEncryptedPuts"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${each.value.arn}/*"]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["AES256"]
    }
  }
}

resource "aws_s3_bucket_policy" "deny_unencrypted" {
  for_each = data.aws_iam_policy_document.deny_unencrypted
  bucket   = aws_s3_bucket.layer[each.key].id
  policy   = each.value.json
}
